CREATE TABLE IF NOT EXISTS migrations (version VARCHAR(100) PRIMARY KEY, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE roles (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE permissions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE role_permissions (role_id INT UNSIGNED NOT NULL, permission_id INT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission_id) REFERENCES permissions(id)) ENGINE=InnoDB;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, role_id INT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, active TINYINT NOT NULL DEFAULT 1, session_version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id)) ENGINE=InnoDB;
CREATE TABLE dentists (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL UNIQUE, name VARCHAR(150) NOT NULL, specialty VARCHAR(150) NOT NULL, active TINYINT NOT NULL DEFAULT 1, work_start TIME NOT NULL DEFAULT '08:00:00', work_end TIME NOT NULL DEFAULT '18:00:00', FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE services (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, description TEXT NOT NULL, price DECIMAL(10,2) NOT NULL DEFAULT 0, duration_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 30, active TINYINT NOT NULL DEFAULT 1, CHECK(price >= 0), CHECK(duration_minutes BETWEEN 15 AND 240)) ENGINE=InnoDB;
CREATE TABLE patients (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, document VARCHAR(40) NOT NULL UNIQUE, birth_date DATE NULL, phone VARCHAR(40) NOT NULL, email VARCHAR(190) NULL, address VARCHAR(255) NULL, emergency_contact VARCHAR(255) NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX patient_name(last_name,first_name), CHECK(status IN ('active','inactive'))) ENGINE=InnoDB;
CREATE TABLE clinical_records (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, patient_id INT UNSIGNED NOT NULL UNIQUE, medical_history TEXT NULL, dental_history TEXT NULL, allergies TEXT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(patient_id) REFERENCES patients(id)) ENGINE=InnoDB;
CREATE TABLE appointments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, patient_id INT UNSIGNED NULL, dentist_id INT UNSIGNED NULL, service_id INT UNSIGNED NOT NULL, contact_name VARCHAR(150) NULL, contact_phone VARCHAR(40) NULL, contact_email VARCHAR(190) NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', reason TEXT NULL, source VARCHAR(20) NOT NULL DEFAULT 'staff', request_key CHAR(64) NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(patient_id) REFERENCES patients(id), FOREIGN KEY(dentist_id) REFERENCES dentists(id), FOREIGN KEY(service_id) REFERENCES services(id), INDEX dentist_slot(dentist_id,starts_at,ends_at,status), INDEX appointment_date(starts_at), CHECK(ends_at > starts_at), CHECK(status IN ('pending','confirmed','attended','completed','cancelled','no_show'))) ENGINE=InnoDB;
CREATE TABLE clinical_record_entries (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, clinical_record_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, medical_history TEXT NULL, dental_history TEXT NULL, allergies TEXT NULL, consultation_reason TEXT NOT NULL, evaluation TEXT NOT NULL, diagnosis TEXT NOT NULL, plan TEXT NOT NULL, procedures TEXT NULL, observation TEXT NULL, correction_of INT UNSIGNED NULL, signed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(clinical_record_id) REFERENCES clinical_records(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(correction_of) REFERENCES clinical_record_entries(id)) ENGINE=InnoDB;
CREATE TABLE teeth (fdi SMALLINT UNSIGNED PRIMARY KEY, dentition VARCHAR(20) NOT NULL, quadrant TINYINT UNSIGNED NOT NULL, position TINYINT UNSIGNED NOT NULL) ENGINE=InnoDB;
CREATE TABLE odontograms (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, clinical_record_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, previous_id INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(clinical_record_id) REFERENCES clinical_records(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(previous_id) REFERENCES odontograms(id)) ENGINE=InnoDB;
CREATE TABLE odontogram_findings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, odontogram_id INT UNSIGNED NOT NULL, tooth_fdi SMALLINT UNSIGNED NOT NULL, surface VARCHAR(20) NOT NULL, state VARCHAR(30) NOT NULL, observation VARCHAR(1000) NULL, UNIQUE(odontogram_id,tooth_fdi,surface), FOREIGN KEY(odontogram_id) REFERENCES odontograms(id), FOREIGN KEY(tooth_fdi) REFERENCES teeth(fdi), CHECK(state IN ('healthy','caries','restoration','missing','planned_procedure','performed')), CHECK(surface IN ('whole','mesial','distal','vestibular','lingual','occlusal'))) ENGINE=InnoDB;
CREATE TABLE treatments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, description TEXT NULL, price DECIMAL(10,2) NOT NULL, duration_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 30, CHECK(price >= 0)) ENGINE=InnoDB;
CREATE TABLE treatment_plans (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, patient_id INT UNSIGNED NOT NULL, dentist_id INT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'planned', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(patient_id) REFERENCES patients(id), FOREIGN KEY(dentist_id) REFERENCES dentists(id), CHECK(status IN ('planned','in_progress','completed','cancelled'))) ENGINE=InnoDB;
CREATE TABLE treatment_plan_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, plan_id INT UNSIGNED NOT NULL, treatment_id INT UNSIGNED NOT NULL, tooth_fdi SMALLINT UNSIGNED NULL, price DECIMAL(10,2) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'planned', notes TEXT NULL, completed_at DATETIME NULL, FOREIGN KEY(plan_id) REFERENCES treatment_plans(id), FOREIGN KEY(treatment_id) REFERENCES treatments(id), FOREIGN KEY(tooth_fdi) REFERENCES teeth(fdi), CHECK(price >= 0), CHECK(status IN ('planned','in_progress','completed','cancelled'))) ENGINE=InnoDB;
CREATE TABLE payments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, plan_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, amount DECIMAL(10,2) NOT NULL, method VARCHAR(30) NOT NULL, reference VARCHAR(150) NULL, request_key CHAR(64) NOT NULL UNIQUE, voided_at DATETIME NULL, voided_by INT UNSIGNED NULL, void_reason VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(plan_id) REFERENCES treatment_plans(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(voided_by) REFERENCES users(id), CHECK(amount > 0), CHECK(method IN ('cash','transfer','card'))) ENGINE=InnoDB;
CREATE TABLE payment_receipts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, payment_id INT UNSIGNED NOT NULL UNIQUE, number VARCHAR(40) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(payment_id) REFERENCES payments(id)) ENGINE=InnoDB;
CREATE TABLE inventory_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, category VARCHAR(100) NOT NULL, unit VARCHAR(40) NOT NULL, stock DECIMAL(12,2) NOT NULL DEFAULT 0, min_stock DECIMAL(12,2) NOT NULL DEFAULT 0, CHECK(stock >= 0), CHECK(min_stock >= 0)) ENGINE=InnoDB;
CREATE TABLE inventory_lots (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, item_id INT UNSIGNED NOT NULL, lot VARCHAR(100) NOT NULL, expires_on DATE NULL, stock DECIMAL(12,2) NOT NULL DEFAULT 0, UNIQUE(item_id,lot), FOREIGN KEY(item_id) REFERENCES inventory_items(id), CHECK(stock >= 0)) ENGINE=InnoDB;
CREATE TABLE inventory_movements (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, item_id INT UNSIGNED NOT NULL, lot_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, quantity DECIMAL(12,2) NOT NULL, reason VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(item_id) REFERENCES inventory_items(id), FOREIGN KEY(lot_id) REFERENCES inventory_lots(id), FOREIGN KEY(user_id) REFERENCES users(id), CHECK(quantity <> 0)) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, action VARCHAR(80) NOT NULL, entity VARCHAR(80) NOT NULL, entity_id INT UNSIGNED NOT NULL DEFAULT 0, detail VARCHAR(1000) NOT NULL DEFAULT '', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), INDEX audit_date(created_at)) ENGINE=InnoDB;
CREATE TABLE password_reset_tokens (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, used_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE remember_tokens (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE auth_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, bucket CHAR(64) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX attempt_bucket(bucket,created_at)) ENGINE=InnoDB;
CREATE TABLE settings (name VARCHAR(100) PRIMARY KEY, value TEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE attachments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, clinical_record_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, original_name VARCHAR(190) NOT NULL, stored_name VARCHAR(80) NOT NULL UNIQUE, mime VARCHAR(100) NOT NULL, size INT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(clinical_record_id) REFERENCES clinical_records(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
